<?php declare(strict_types=1);use FMonitor2\YiiRuntime\ViewSupport;use yii\helpers\Html;ViewSupport::begin($this,'Экономика объектов',$identity,'otiz','wide');$rub=static fn(?int$c)=>$c===null?'—':number_format($c/100,2,',',' ').' ₽';?>
<main class="fm2-otiz fm2-otiz-page"><section class="fm2-otiz-surface"><div class="fm2-otiz-tabs-surface"><?=$this->render('_otiz-nav',['current'=>'objects'])?></div></section><header class="fm2-page-header"><div><h1>Экономика объектов</h1><p>Полный портфель, признанные обязательства и выплаты</p></div><span><?=(int)$economy['total']?> объектов</span></header>
<section class="fm2-otiz-register-summary"><div><span>Утверждено</span><strong><?=$rub($economy['summary']['approvedCents'])?></strong></div><div><span>Выплачено</span><strong><?=$rub($economy['summary']['paidCents'])?></strong></div><div><span>Ожидает выплаты</span><strong><?=$rub($economy['summary']['payableCents'])?></strong></div></section>
<form method="get" action="/pilot/otiz/objects"><label>Поиск<input class="shlz-input" name="q" value="<?=Html::encode((string)($query['q']??''))?>"></label><?=ViewSupport::choice('year',(string)($query['year']??'all'),array_combine(array_merge(['all'],$economy['facets']['years']),array_merge(['Все годы'],$economy['facets']['years'])),'Год')?><?=ViewSupport::choice('sort',(string)($query['sort']??'regnumber_asc'),['regnumber_asc'=>'Рег. номер по возрастанию','regnumber_desc'=>'Рег. номер по убыванию'],'Сортировка')?><button class="shlz-button shlz-button--primary">Показать</button></form>
<section class="fm2-otiz-surface"><div class="shlz-table-wrap" tabindex="0"><table class="shlz-table"><thead><tr><th>Объект</th><th>Год</th><th>Фонд</th><th>Утверждено</th><th>Выплачено</th><th>Ожидает выплаты</th></tr></thead><tbody><?php foreach($economy['rows']as$row):?><tr><td><a href="/pilot/objects/<?=(int)$row['objectId']?>"><?=Html::encode($row['regnumber'])?></a><small><?=Html::encode($row['address'])?></small></td><td><?=Html::encode($row['year'])?></td><td><?=$rub($row['fundCents'])?></td><td><?=$rub($row['approvedCents']??null)?></td><td><?=$rub($row['paidCents']??null)?></td><td><strong><?=$rub($row['payableCents'])?></strong><?php foreach($row['payableCalculations']as$calculation):?><div><a href="/pilot/otiz/calculations/<?=(int)$calculation['calculationId']?>#object-<?=(int)$row['objectId']?>">Расчёт #<?=(int)$calculation['calculationId']?></a><small>Вклад объекта: <?=$rub($calculation['objectContributionCents']??null)?> · остаток всего расчёта: <?=$rub($calculation['calculationRemainingCents']??null)?></small></div><?php endforeach?><?php if(($row['diagnostic']??null)!==null):?><small><?=Html::encode((string)$row['diagnostic'])?></small><?php endif?></td></tr><?php endforeach?></tbody></table></div></section>
<?=ViewSupport::pagination('/pilot/otiz/objects',(int)$economy['page'],max(1,(int)ceil($economy['total']/$economy['pageSize'])),$economy['total'],$economy['pageSize'],['q'=>$query['q']??'','year'=>$query['year']??'all','sort'=>$query['sort']??'regnumber_asc'],'Страницы экономики ОТиЗ')?></main><?php ViewSupport::end($this);?>
